import React, {useEffect, useRef, useState} from 'react';
import {
  ActivityIndicator,
  InteractionManager,
  Keyboard,
  Modal,
  Platform,
  TouchableOpacity,
  View,
} from 'react-native';
import styles from './activation-modal.styles';
import {ActivationModalProps} from './activation-modal.props';
import AppText from '@components/app-text/app-text';
import TextInputComponent from '@components/text-input-component/text-input-component';
import ActivationCode from '../../assets/images/activation_code.svg';
import CheckCircle from '../../assets/images/check-circle.svg';
import GradientBt from '@components/gradient-bt/gradient-bt';

interface ActivateApiError {
  error?: {
    message?: string;
  };
  message?: string;
}

interface ActivateApiResult {
  success?: boolean;
  error?: {
    message?: string;
  };
}

const ANDROID_MODAL_HIDE_DELAY_MS = 300;

const ActivationModal: React.FC<ActivationModalProps> = (
  props: ActivationModalProps,
) => {
  const [showActivateModal, setShowActivateModal] = useState<boolean>(false);
  const [activationCode, setActivationCode] = useState<string>('');
  const [errorMessage, setErrorMessage] = useState<string>('');
  const [isActivating, setIsActivating] = useState<boolean>(false);
  const [isActivated, setIsActivated] = useState<boolean>(false);
  const propsRef = useRef<ActivationModalProps>(props);
  const pendingHideRef = useRef<boolean>(false);
  const pendingRefreshRef = useRef<boolean>(false);

  propsRef.current = props;

  useEffect(() => {
    init();
  }, [props.visible]);

  const init = (): void => {
    setShowActivateModal(props.visible);
    setIsActivated(false);
    if (props.activationCode !== '') {
      setActivationCode(props.activationCode);
    }
  };

  const flushHideCallback = (): void => {
    if (!pendingHideRef.current) {
      return;
    }
    pendingHideRef.current = false;
    const shouldRefresh = pendingRefreshRef.current;
    pendingRefreshRef.current = false;
    const currentProps = propsRef.current;
    currentProps.onActivationModalHide(false, shouldRefresh);
    if (shouldRefresh) {
      currentProps.onActivationSuccess?.();
    }
  };

  const finishActivation = (shouldRefresh: boolean): void => {
    Keyboard.dismiss();
    pendingRefreshRef.current = shouldRefresh;
    pendingHideRef.current = true;
    setActivationCode('');
    setErrorMessage('');
    setShowActivateModal(false);
  };

  useEffect(() => {
    if (showActivateModal || !pendingHideRef.current) {
      return;
    }
    if (Platform.OS !== 'android') {
      return;
    }
    const interactionTask = InteractionManager.runAfterInteractions(() => {
      setTimeout(() => {
        flushHideCallback();
      }, ANDROID_MODAL_HIDE_DELAY_MS);
    });
    return () => {
      interactionTask.cancel();
    };
  }, [showActivateModal]);

  const handleActivateCode = async (): Promise<void> => {
    setIsActivating(true);
    setErrorMessage('');
    Keyboard.dismiss();
    try {
      const res = (await $api.activate(activationCode)) as ActivateApiResult;
      if (res?.success) {
        setIsActivated(true);
        if (props.onActivationSuccess) {
          finishActivation(true);
        }
        return;
      }
      setErrorMessage(res?.error?.message ?? 'invalid_activation_code');
    } catch (error) {
      const activateError = error as ActivateApiError;
      setErrorMessage(
        activateError?.error?.message ??
          activateError?.message ??
          'invalid_activation_code',
      );
    } finally {
      setIsActivating(false);
    }
  };

  const handleOktBtnSuccessResult = (): void => {
    finishActivation(true);
  };

  const handleCancelBtn = (): void => {
    finishActivation(false);
  };

  const renderSuccessResult = (): React.ReactElement => {
    return (
      <View style={styles.activateModalContainer}>
        <View style={styles.subActivateModalContainer}>
          <View>
            <CheckCircle width={80} height={80} />
          </View>
          <AppText style={styles.modalTitle}>
            {$i18n.t('activate_success')}
          </AppText>
          <AppText style={styles.activatesuccess1}>
            {$i18n.t('activate_success1')}
          </AppText>
          <TouchableOpacity
            onPress={handleOktBtnSuccessResult}
            style={styles.okbtn}>
            <AppText style={styles.innerOkbtnContainer}>
              {$i18n.t('ok')}
            </AppText>
          </TouchableOpacity>
        </View>
      </View>
    );
  };

  const renderActivationCode = (): React.ReactElement => {
    return (
      <View style={styles.activateModalContainer}>
        <View style={styles.subActivateModalContainer}>
          <View style={styles.subActivateModal}>
            <ActivationCode height={85} width={136} />
            <AppText size={'xlarge'}>
              {$i18n.t('activation_code')}
            </AppText>
          </View>
          <View style={styles.activationCodeInputContainer}>
            <TextInputComponent
              onChangeText={e => setActivationCode(e)}
              value={activationCode}
              placeholder={$i18n.t('validation.activation_code_required')}
              keyboardType="default"
              style={styles.activationTextInputStyle}
            />
          </View>
          {errorMessage !== '' && (
              <AppText style={{color: "#D1224D", marginTop: 4}}>
                {$i18n.t(errorMessage)}
              </AppText>
            )
            }
          <View style={styles.requiredContainer}>
            <AppText style={styles.labelAsterisk}>{`•`}</AppText>
            <AppText style={styles.validationRequired}>
              {$i18n.t('validation.activation_code_required1')}
            </AppText>
          </View>
          <View style={styles.buttonContainer}>
            <TouchableOpacity
              style={styles.cancelBtnContainer}
              onPress={handleCancelBtn}>
              <AppText style={styles.cancelTextCtonair}>
                {$i18n.t('cancel')}
              </AppText>
            </TouchableOpacity>
            <GradientBt
              gradientStyle={[styles.activateTextContainer]}
              onPress={() => handleActivateCode()}
              disabled={isActivating || activationCode === '' ? true : false}
            >
              {isActivating
                ? <ActivityIndicator
                    size="small"
                    color="#00AC86"
                    style={{marginRight: 12}}
                  />
                : <AppText style={styles.activateAppText}>
                    {$i18n.t('activate')}
                  </AppText>
              }
            </GradientBt>
          </View>
        </View>
      </View>
    );
  };

  const renderActivateModal = (): React.ReactElement => {
    return (
      <Modal
        animationType="slide"
        transparent={true}
        visible={showActivateModal}
        onDismiss={() => {
          if (Platform.OS === 'ios') {
            flushHideCallback();
          }
        }}
        onRequestClose={handleCancelBtn}>
        {!isActivated
          ? <>{renderActivationCode()}</>
          : <>{renderSuccessResult()}</>
        }
      </Modal>
    );
  };

  if (!showActivateModal && !pendingHideRef.current) {
    return null;
  }

  return (
    <>
      {renderActivateModal()}
    </>
  );
};

export default ActivationModal;

